#include <iomanip>
using namespace std;

int main() {
    long long a;
    long long b;
    long long c;
    cin >> a >> b >> c;

    double average = (a + b + c) / 3.0;
    cout << fixed << setprecision(2) << average << endl;

    return 0;
}

